/**
 * Texas Principles of Real Estate I — formative assessment bank.
 *
 * WHAT THIS BANK IS AND IS NOT. These are the course's FORMATIVE instruments: topic quizzes the
 * student must clear to progress, and the scenario exercises the course design requires. They are
 * instructional artifacts — every item teaches through its rationale. This file is NOT the final
 * examination: TX-1B is not authorized, no final bank exists, and nothing here may be promoted into
 * one without the TX-1B build.
 *
 * THE PROGRESSION CONTRACT. A student must answer each topic's required questions correctly before
 * the next topic opens. An incorrect answer shows the RATIONALE, sends the student to the
 * REMEDIATION anchor in the module text, and then serves the item's REPLACEMENT — a related question
 * on the same proposition — which counts toward passing only if answered correctly. Attempts are
 * logged. That contract is stated in the TX-1A work order as course design; whether any Commission
 * rule separately mandates it is UNVERIFIED until the codified 22 TAC is read, and no document may
 * describe it as a TREC mandate.
 *
 * TRACEABILITY. Every item's `tests` names the module unit it examines, and every legal proposition
 * in a prompt or rationale is taught in that unit from a section recorded as read in
 * config/texas/statute-sources.mjs. The tests enforce both directions.
 */

const quiz = (id, tests, prompt, choices, correctChoice, rationale, remediation, replacement) =>
  Object.freeze({ id, tests, prompt, choices: Object.freeze(choices), correctChoice, rationale, remediation, replacement: Object.freeze(replacement) });

